-- =============================================================================
-- LOCAL DB FULL REFRESH — WeCMS-Vietnam baseline tenant VN_VNM0004_000001
-- Target:    localhost:5434 / wecms_dev / schema public
-- Source:    JEX DEV DB (wecmsvndev), snapshot pulled 2026-04-23
-- Flyway:    LOCAL is Flyway-managed — if you want this versioned, rename to
--            `src/main/resources/db/migration/V11__refresh_from_jex_dev_20260423.sql`
--            inside wecms-api. The SQL below is Flyway-compatible (no
--            psql meta-commands, no \prompt, no \copy).
--
-- SCOPE — 6 target tables, all filtered by biz_key = 'VN_VNM0004_000001'
--   Existing on LOCAL         : busi_infm, user_infm, user_busi_conn_infm, user_login_his
--   Missing on LOCAL (created): empl_infm, busi_admn_infm
--
-- WHAT THIS SCRIPT DOES
--   Step A  Backup current LOCAL rows into *_bkp_20260423 tables
--   Step B  Create missing tables (empl_infm, busi_admn_infm) — LOCAL timestamptz style
--   Step C  Delete the placeholder/partial WeCMS-scope rows
--           (non-WeCMS rows are already zero — Flyway V6 scoped to single tenant)
--   Step D  Seed fresh data from DEV
--              1 busi_infm  +  99 user_infm  +  99 user_busi_conn_infm
--              +  7 busi_admn_infm  +  1 empl_infm
--           user_login_his is NOT seeded inline (12,714 rows — see STEP E footnote).
--   Step E  Verify row counts.
--
-- TYPE CONVERSION NOTE
--   DEV stores reg_dtm/mod_dtm/join_dt as varchar(14) 'YYYYMMDDHH24MISS'.
--   LOCAL stores them as timestamptz. All timestamp columns are converted at
--   INSERT time via (to_timestamp(..., 'YYYYMMDDHH24MISS') AT TIME ZONE 'UTC').
--   DEV varchar(8) date columns (use_date_from/_to, free_use_date_*, etc.)
--   are converted via to_date(..., 'YYYYMMDD').
--
-- HOW TO RUN  (any PostgreSQL client — DBeaver, psql, pgAdmin)
--   Open this file → Execute All → confirm the verification output → COMMIT.
-- =============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- STEP A — BACKUP current LOCAL rows (timestamped, one-shot)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS busi_infm_bkp_20260423;
DROP TABLE IF EXISTS user_infm_bkp_20260423;
DROP TABLE IF EXISTS user_busi_conn_infm_bkp_20260423;
DROP TABLE IF EXISTS user_login_his_bkp_20260423;

CREATE TABLE busi_infm_bkp_20260423           AS SELECT * FROM busi_infm;
CREATE TABLE user_infm_bkp_20260423           AS SELECT * FROM user_infm;
CREATE TABLE user_busi_conn_infm_bkp_20260423 AS SELECT * FROM user_busi_conn_infm;
CREATE TABLE user_login_his_bkp_20260423      AS SELECT * FROM user_login_his;

-- ----------------------------------------------------------------------------
-- STEP B — CREATE missing tables (LOCAL timestamptz convention, matching
--          DEV column order but with LOCAL's Spring Boot-compatible types)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS empl_infm (
    biz_key                varchar(32)   NOT NULL,
    empl_no                varchar(20)   NOT NULL,
    empl_nm                varchar(100),
    jbcl_nm                varchar(100),
    dept_nm                varchar(100),
    clph_no                varchar(100),
    eml                    varchar(100),
    cmpn_join_date         date,
    cmpn_fire_date         date,
    empl_resi_st           varchar(200),
    empl_resi_city         varchar(200),
    empl_resi_dtl_adrs     varchar(200),
    empl_resi_post_adrs    varchar(200),
    user_img               varchar(500),
    natn_id                varchar(20),
    bank_cd                varchar(20),
    acct_no                varchar(100),
    mapp_seup_yn           varchar(1)    NOT NULL DEFAULT 'N',
    mapp_noti_yn           varchar(1)    NOT NULL DEFAULT 'N',
    payroll_page_reg_yn    varchar(1)    NOT NULL DEFAULT 'N',
    wabooks_emp_mng_reg_yn varchar(1)    NOT NULL DEFAULT 'Y',
    reg_id                 varchar(50)   NOT NULL,
    reg_dtm                timestamptz   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mod_id                 varchar(50),
    mod_dtm                timestamptz,
    tel_no                 varchar(100),
    empl_no_auto_gen_yn    varchar(1)    NOT NULL DEFAULT 'N',
    r_empl_no              varchar(50)   NOT NULL,
    gender_cd              varchar(1),
    birth_date             date,
    natn_num_cd            varchar(5),
    citizen_natn_num_cd    varchar(5),
    empl_iden_type         varchar(1),
    emer_clph              varchar(100),
    resi_yn                varchar(1),
    mari_yn                varchar(1),
    child_dep              numeric,
    efil_dept_nm           varchar(100),
    eng_fst_nm             varchar(100),
    eng_lst_nm             varchar(100),
    nat_fst_nm             varchar(100),
    nat_lst_nm             varchar(100),
    actv_yn                varchar(1)    NOT NULL DEFAULT 'Y',
    CONSTRAINT empl_infm_pk    PRIMARY KEY (biz_key, empl_no),
    CONSTRAINT empl_infm_uk01  UNIQUE      (biz_key, r_empl_no),
    CONSTRAINT empl_infm_fk01  FOREIGN KEY (biz_key) REFERENCES busi_infm(biz_key)
);

CREATE TABLE IF NOT EXISTS busi_admn_infm (
    biz_key  varchar(32)  NOT NULL,
    user_id  varchar(50)  NOT NULL,
    user_nm  varchar(100) NOT NULL,
    reg_id   varchar(50)  NOT NULL,
    reg_dtm  timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mod_id   varchar(50)  NOT NULL,
    mod_dtm  timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT busi_admn_infm_pk   PRIMARY KEY (biz_key, user_id),
    CONSTRAINT busi_admn_infm_fk01 FOREIGN KEY (biz_key) REFERENCES busi_infm(biz_key),
    CONSTRAINT busi_admn_infm_fk02 FOREIGN KEY (user_id) REFERENCES user_infm(user_id)
);

-- ----------------------------------------------------------------------------
-- STEP C — CLEAN existing WeCMS-scope rows (placeholder + partial seed)
--          Order respects FKs (children first, parents last).
-- ----------------------------------------------------------------------------
DELETE FROM user_login_his;
DELETE FROM user_busi_conn_infm;
DELETE FROM busi_admn_infm;
DELETE FROM empl_infm;
DELETE FROM user_infm;
DELETE FROM busi_infm;

-- ----------------------------------------------------------------------------
-- STEP D — SEED from DEV
-- ----------------------------------------------------------------------------

-- -- D.1 busi_infm — 1 baseline root row --------------------------------------

-- -- D.2 user_infm — 99 users --------------------------------------------------

-- -- D.3 user_busi_conn_infm — 99 user↔business conns --------------------------

-- -- D.4 busi_admn_infm — 7 admin bindings -------------------------------------

-- -- D.5 empl_infm — 1 employee row --------------------------------------------

-- ----------------------------------------------------------------------------
-- STEP E — VERIFY (read the counts BEFORE committing)
-- ----------------------------------------------------------------------------
SELECT 'busi_infm'                           AS tbl, COUNT(*)::bigint AS rows, 1::bigint    AS expected FROM busi_infm
UNION ALL SELECT 'user_infm',                 COUNT(*),                         99           FROM user_infm
UNION ALL SELECT 'user_busi_conn_infm',       COUNT(*),                         99           FROM user_busi_conn_infm
UNION ALL SELECT 'busi_admn_infm',            COUNT(*),                         7            FROM busi_admn_infm
UNION ALL SELECT 'empl_infm',                 COUNT(*),                         1            FROM empl_infm
UNION ALL SELECT 'user_login_his (not seeded)', COUNT(*),                       0            FROM user_login_his
UNION ALL SELECT 'busi_infm NON-WeCMS (=0)',  COUNT(*),                         0            FROM busi_infm           WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'conn NON-WeCMS (=0)',       COUNT(*),                         0            FROM user_busi_conn_infm WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'admn NON-WeCMS (=0)',       COUNT(*),                         0            FROM busi_admn_infm      WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'empl NON-WeCMS (=0)',       COUNT(*),                         0            FROM empl_infm           WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'user_infm orphans (=0)',    COUNT(*),                         0
  FROM user_infm u WHERE NOT EXISTS (SELECT 1 FROM user_busi_conn_infm c WHERE c.user_id=u.user_id)
ORDER BY 1;

-- If every "expected" column matches "rows" and the NON-WeCMS/orphan checks are zero,
-- commit.  Otherwise run ROLLBACK and investigate.

-- COMMIT;    -- ← UNCOMMENT after reviewing the verify output above
-- ROLLBACK;  -- ← or this, to discard everything (incl. the backup tables and the DDL)

-- =============================================================================
-- user_login_his — NOT seeded inline (12,714 rows)
-- =============================================================================
-- Run this AFTER committing the transaction above. Two options:
--
-- Option 1 (simple): leave user_login_his empty. The login feature will
--   accumulate new history rows as users log in.
--
-- Option 2 (full legacy history): export from DEV, import into LOCAL.
--   On a machine with psql access to both DBs:
--
--     psql "host=10.254.242.254 port=54311 dbname=wecmsvndevdb user=wecmsvndev" \
--       -c "\copy (SELECT user_id,
--                         (to_timestamp(reg_dtm,'YYYYMMDDHH24MISS') AT TIME ZONE 'UTC') AS reg_dtm,
--                         ip_addr, lgn_chnl, rslt_cd, rslt_cont
--                  FROM wecmsvndev.user_login_his
--                  WHERE user_id IN (SELECT user_id FROM wecmsvndev.user_busi_conn_infm
--                                    WHERE biz_key='VN_VNM0004_000001')) \
--            TO 'user_login_his_000001.csv' WITH (FORMAT csv, HEADER true)"
--
--     psql "host=localhost port=5434 dbname=wecms_dev user=postgres" \
--       -c "\copy user_login_his (user_id,reg_dtm,ip_addr,lgn_chnl,rslt_cd,rslt_cont) \
--            FROM 'user_login_his_000001.csv' WITH (FORMAT csv, HEADER true)"
--
-- LOCAL user_login_his PK is (user_id, reg_dtm) — no reg_uid column.
-- Dedup before import if both logs share the same (user_id, reg_dtm) second.
-- =============================================================================

-- =============================================================================
-- ROLLBACK SAFETY — backup tables retained
-- =============================================================================
-- After a successful COMMIT, the *_bkp_20260423 tables remain as a rollback
-- point. Drop them once you're confident the refresh is correct:
--
--   DROP TABLE busi_infm_bkp_20260423, user_infm_bkp_20260423,
--              user_busi_conn_infm_bkp_20260423, user_login_his_bkp_20260423;
